INSERT OR IGNORE INTO self_check_tests
  (id, slug, version, title, description, subject, topic, level, estimated_minutes, status)
VALUES
  ('algebraicke-vyrazy-9-dan-v1', 'algebraicke-vyrazy-9', 1,
   'Algebraické výrazy — diagnostický self-check (9. třída)',
   '[[calculator:Bez kalkulačky]]12 úloh / 23 bodů / cca 25 minut. Procvičuje vzorce pro druhé mocniny součtu a rozdílu, rozdíl čtverců, rozklad výrazů, odstraňování vnořených závorek a odhad. U každé otázky vyber jednu odpověď; po vyhodnocení se zobrazí správné řešení a vysvětlení.', 'Matematika', 'Algebraické výrazy', '9. třída / příprava na SŠ', 25, 'published');

INSERT OR IGNORE INTO self_check_questions
  (id, test_id, position, prompt, options_json, correct_answer, explanation, points)
VALUES
  ('algebraicke-vyrazy-9-dan-v1-q1', 'algebraicke-vyrazy-9-dan-v1', 1, '{"instruction":"Roznásob a zjednoduš výraz.","math":"(x+4)^2","category":"Vzorce a úprava výrazů","hint":"Použij vzorec pro druhou mocninu součtu."}', '[{"id":"a","label":"[[math:x^2+16]]"},{"id":"b","label":"[[math:x^2+8x+16]]"},{"id":"c","label":"[[math:x^2+4x+16]]"},{"id":"d","label":"[[math:2x+8]]"}]', 'b', 'Použijeme [[math:(a+b)^2=a^2+2ab+b^2]]. Proto [[math:(x+4)^2=x^2+8x+16]].', 1),
  ('algebraicke-vyrazy-9-dan-v1-q2', 'algebraicke-vyrazy-9-dan-v1', 2, '{"instruction":"Roznásob a zjednoduš výraz.","math":"(2a-3)^2","category":"Vzorce a úprava výrazů","hint":"Nezapomeň, že prostřední člen je [[math:-2\\cdot2a\\cdot3]]."}', '[{"id":"a","label":"[[math:4a^2-12a+9]]"},{"id":"b","label":"[[math:4a^2-6a+9]]"},{"id":"c","label":"[[math:4a^2+12a+9]]"},{"id":"d","label":"[[math:2a^2-12a+9]]"}]', 'a', 'Podle [[math:(u-v)^2=u^2-2uv+v^2]] je [[math:(2a-3)^2=(2a)^2-2\cdot2a\cdot3+3^2=4a^2-12a+9]].', 2),
  ('algebraicke-vyrazy-9-dan-v1-q3', 'algebraicke-vyrazy-9-dan-v1', 3, '{"instruction":"Využij vzorec a uprav součin.","math":"(3x+5)(3x-5)","category":"Vzorce a úprava výrazů","hint":"Jde o součin součtu a rozdílu stejných dvou členů."}', '[{"id":"a","label":"[[math:9x^2+25]]"},{"id":"b","label":"[[math:9x^2-30x+25]]"},{"id":"c","label":"[[math:9x^2-25]]"},{"id":"d","label":"[[math:6x^2-25]]"}]', 'c', 'Platí [[math:(u+v)(u-v)=u^2-v^2]]. Zde [[math:u=3x]] a [[math:v=5]], tedy výsledek je [[math:9x^2-25]].', 2),
  ('algebraicke-vyrazy-9-dan-v1-q4', 'algebraicke-vyrazy-9-dan-v1', 4, '{"instruction":"Který vzorec správně upravuje druhou mocninu rozdílu?","math":"(a-b)^2=?","category":"Vzorce a úprava výrazů","hint":"Prostřední člen má záporné znaménko a obsahuje součin obou členů."}', '[{"id":"a","label":"[[math:a^2-b^2]]"},{"id":"b","label":"[[math:a^2+2ab+b^2]]"},{"id":"c","label":"[[math:a^2-2ab+b^2]]"},{"id":"d","label":"[[math:a^2-ab+b^2]]"}]', 'c', 'Druhá mocnina rozdílu je [[math:(a-b)^2=a^2-2ab+b^2]].', 1),
  ('algebraicke-vyrazy-9-dan-v1-q5', 'algebraicke-vyrazy-9-dan-v1', 5, '{"instruction":"Rozlož výraz na součin pomocí vzorce.","math":"x^2-49","category":"Rozklad podle vzorců","hint":"Rozdíl čtverců má tvar [[math:u^2-v^2=(u-v)(u+v)]]."}', '[{"id":"a","label":"[[math:(x-7)^2]]"},{"id":"b","label":"[[math:(x-7)(x+7)]]"},{"id":"c","label":"[[math:(x-49)(x+1)]]"},{"id":"d","label":"[[math:(x+7)^2]]"}]', 'b', '[[math:x^2-49=x^2-7^2=(x-7)(x+7)]].', 2),
  ('algebraicke-vyrazy-9-dan-v1-q6', 'algebraicke-vyrazy-9-dan-v1', 6, '{"instruction":"Zapiš trojčlen jako druhou mocninu dvojčlenu.","math":"4x^2+12x+9","category":"Rozklad podle vzorců","hint":"První a poslední člen jsou druhé mocniny. Zkontroluj jejich dvojnásobný součin."}', '[{"id":"a","label":"[[math:(2x-3)^2]]"},{"id":"b","label":"[[math:(4x+3)^2]]"},{"id":"c","label":"[[math:(2x+3)^2]]"},{"id":"d","label":"[[math:(2x+9)^2]]"}]', 'c', '[[math:(2x+3)^2=4x^2+12x+9]], takže hledaný rozklad je [[math:(2x+3)^2]].', 2),
  ('algebraicke-vyrazy-9-dan-v1-q7', 'algebraicke-vyrazy-9-dan-v1', 7, '{"instruction":"Odstraň vnitřní závorky a zjednoduš výraz.","math":"3x-(2x-(x-4))","category":"Závorky","hint":"Postupuj od nejvnitřnější závorky. Mínus před závorkou změní znaménka všech členů."}', '[{"id":"a","label":"[[math:2x-4]]"},{"id":"b","label":"[[math:2x+4]]"},{"id":"c","label":"[[math:4x-4]]"},{"id":"d","label":"[[math:4]]"}]', 'a', 'Nejprve [[math:2x-(x-4)=2x-x+4=x+4]]. Potom [[math:3x-(x+4)=3x-x-4=2x-4]].', 2),
  ('algebraicke-vyrazy-9-dan-v1-q8', 'algebraicke-vyrazy-9-dan-v1', 8, '{"instruction":"Odstraň závorky a sečti podobné členy.","math":"-2a+3(a-4b)-(b-a)","category":"Závorky","hint":"Při odstraňování závorek násob nejprve každý člen a hlídej znaménko před poslední závorkou."}', '[{"id":"a","label":"[[math:2a-13b]]"},{"id":"b","label":"[[math:2a-11b]]"},{"id":"c","label":"[[math:4a-13b]]"},{"id":"d","label":"[[math:4a-11b]]"}]', 'a', '[[math:-2a+3a-12b-b+a=( -2a+3a+a)+(-12b-b)=2a-13b]].', 2),
  ('algebraicke-vyrazy-9-dan-v1-q9', 'algebraicke-vyrazy-9-dan-v1', 9, '{"instruction":"Který výraz je správným rozvojem druhé mocniny?","math":"(2x-5)^2","category":"Vzorce a kontrola","hint":"Prostřední člen je dvojnásobek součinu [[math:2x]] a [[math:-5]]."}', '[{"id":"a","label":"[[math:4x^2-25]]"},{"id":"b","label":"[[math:4x^2-10x+25]]"},{"id":"c","label":"[[math:4x^2-20x+25]]"},{"id":"d","label":"[[math:2x^2-20x+25]]"}]', 'c', '[[math:(2x-5)^2=(2x)^2-2\cdot2x\cdot5+5^2=4x^2-20x+25]].', 2),
  ('algebraicke-vyrazy-9-dan-v1-q10', 'algebraicke-vyrazy-9-dan-v1', 10, '{"instruction":"Vypočti součin chytře pomocí vzorce.","math":"1003\\cdot997","category":"Odhad a vzorce","hint":"Přepiš činitele jako [[math:(1000+3)(1000-3)]]."}', '[{"id":"a","label":"[[math:999991]]"},{"id":"b","label":"[[math:1000000]]"},{"id":"c","label":"[[math:999700]]"},{"id":"d","label":"[[math:1000009]]"}]', 'a', 'Jde o rozdíl čtverců: [[math:(1000+3)(1000-3)=1000^2-3^2=1000000-9=999991]].', 2),
  ('algebraicke-vyrazy-9-dan-v1-q11', 'algebraicke-vyrazy-9-dan-v1', 11, '{"instruction":"Která hodnota je nejlepším odhadem čísla [[math:49{,}8^2]]?","math":"","category":"Odhad a vzorce","hint":"Vezmi [[math:49{,}8]] jako číslo blízké 50 a odhadni druhou mocninu."}', '[{"id":"a","label":"[[math:2400]]"},{"id":"b","label":"[[math:2480]]"},{"id":"c","label":"[[math:2500]]"},{"id":"d","label":"[[math:2600]]"}]', 'b', '[[math:49{,}8^2=(50-0{,}2)^2=2500-20+0{,}04=2480{,}04]]. Nejlepší nabízený odhad je [[math:2480]].', 2),
  ('algebraicke-vyrazy-9-dan-v1-q12', 'algebraicke-vyrazy-9-dan-v1', 12, '{"instruction":"Uprav výraz co nejjednodušeji.","math":"(x+2)^2-(x-2)(x+2)","category":"Kombinace vzorců","hint":"Rozviň první část jako druhou mocninu součtu a druhou jako rozdíl čtverců."}', '[{"id":"a","label":"[[math:4x+8]]"},{"id":"b","label":"[[math:4x]]"},{"id":"c","label":"[[math:2x^2+4]]"},{"id":"d","label":"[[math:2x+8]]"}]', 'a', '[[math:(x+2)^2=x^2+4x+4]] a [[math:(x-2)(x+2)=x^2-4]]. Po odečtení: [[math:x^2+4x+4-(x^2-4)=4x+8]].', 3);
